with limits as (select key c,value::integer mx from jsonb_each_text('{"C0":19,"C1":6,"C2":6,"C3":8,"C4":9,"C5":8,"C6":8,"C7":4,"C8":9,"C9":11,"C10":6,"C11":8,"C12":6,"C13":4,"C14":4,"C15":4,"C16":5,"C17":9,"C18":5,"C19":4,"C20":7,"C21":6,"C22":4,"C23":7,"C24":7,"C25":4,"C26":8,"C27":12,"C28":12,"C29":10,"C30":7,"C31":12,"C32":10,"C33":7,"C34":9,"C35":8,"C36":10,"C37":13,"C38":8,"C39":9,"C40":7,"C41":8,"C42":8,"C43":6,"C44":6,"C45":7,"C46":8,"C47":5,"C48":4,"C49":7,"C50":7,"C51":8,"C52":5,"C53":8,"C54":7,"C55":9,"C56":8,"C57":8,"C58":8,"C59":10,"C60":10,"C61":9,"C62":8,"C63":8,"C64":4,"C65":7,"C66":8,"C67":8,"C68":7,"C69":5,"C70":5,"C71":4,"C72":6,"C73":5}'::jsonb)),
plans as (select c,mx,jsonb_build_object('courseKey',c,'sessionIndex',mx,'startDate','2026-11-05','speed',speed,'amount',speed,'cadence',cadence,'pace','p2','curriculumRevision','20261104-curriculum3') p from limits cross join unnest(array[0.7,0.85,1,1.25,1.5]) speed cross join unnest(array['w1','w2']) cadence),
cases as (select 'valid_current' kind,p,true expected from plans union all select 'above_end',p||jsonb_build_object('sessionIndex',mx+1),false from plans union all select 'zero_session',p||'{"sessionIndex":0}'::jsonb,false from plans union all select 'old_revision',p||'{"curriculumRevision":"20261026-curriculum2"}'::jsonb,false from plans union all select 'unknown_revision',p||'{"curriculumRevision":"future"}'::jsonb,false from plans union all select 'missing_revision',p-'curriculumRevision',true from plans),
checked as (select kind,expected,case when expected then nm_private.canonical_delivery_plan(p)=p else nm_private.canonical_delivery_plan(p) is null end passed from cases)
select kind,count(*) total,count(*) filter(where passed) passed from checked group by kind order by kind;
